parts.openscad_module:
$fn = 64;

rod_diameter     = 8;
lm_od            = 15.1;
rod_spacing      = 40;
screw_diameter   = 8;
nut_od           = 22;
nut_height       = 10;
nut_bolt_circle  = 16;
side_wall        = 5;
top_wall         = 4;
end_wall         = 6;

car_l = 24 + 2*end_wall;
car_w = rod_spacing + lm_od + 2*side_wall;
car_h = lm_od + top_wall;

module t8_nut_carriage() {
  difference() {
    cube([car_l, car_w, car_h], center = true);
    for (y = [-rod_spacing/2, rod_spacing/2])
      translate([0, y, -top_wall/2])
        rotate([0, 90, 0])
          cylinder(h = car_l + 2, d = lm_od, center = true, $fn = 64);
    cylinder(h = car_h + 2, d = screw_diameter + 1.5, center = true, $fn = 48);
    translate([0, 0, car_h/2 - nut_height/2])
      cylinder(h = nut_height + 0.5, d = nut_od + 0.4, center = true, $fn = 64);
    for (a = [0, 90, 180, 270])
      rotate([0, 0, a])
        translate([nut_bolt_circle/2, 0, car_h/2 - nut_height/2])
          cylinder(h = nut_height + 6, d = 3.4, center = true, $fn = 32);
  }
}

t8_nut_carriage();
